---@class UIRolePlotChapterNode
---@field QuestCell                     	UnityEngine.RectTransform               
---@field QuestListLayout               	UnityEngine.RectTransform               
---@field ChapterCell                   	UnityEngine.Animator                    
---@field BtnGetReward                  	UnityEngine.RectTransform               
---@field LockNode                      	UnityEngine.RectTransform               
