---@field TxtChapterName                	UnityEngine.RectTransform               
---@field PhotoBg                       	UnityEngine.RectTransform                                           
local UIRolePlotChapterNode = Class("UIRolePlotChapterNode")
function UIRolePlotChapterNode:__init() 
    self._data = nil
end

function UIRolePlotChapterNode:__delete()
    self._data = nil
end

function UIRolePlotChapterNode:Awake()
    SetButtonAction(self.BtnGift, Bind(self, self.OnBtnGift))
    SetButtonAction(self.ButtonGroup, Bind(self, self.OnBtnEnterChapter))

    self.eventRedpointDataChange = Events.AddListener(Constants.EventNames.RedpointDataChange, Bind(self, self.RefreshRedGo))
end

function UIRolePlotChapterNode:Start()
end

function UIRolePlotChapterNode:RefreshRedGo()
    if not self._data then
        return
    end
    CfUtils.SetActive(self.redPoint, QuestConfMgr:GetInstance():IsHasDrawRewardId(self._data.id)) 
end

function UIRolePlotChapterNode:UpdateContent(data)
    if not data then
        return
    end
    self._data = data

    local allNum, hasNum = QuestConfMgr:GetInstance():GetRoleStoryChapterOverFinaleIdNum(self._data.id)
    CfUtils.FillText(self.TxtNumber, hasNum.."/"..allNum)


    CfUtils.FillImage(self.ImgChapterBg, data.sectionIcon)
    CfUtils.FillText(self.TxtChapterName, data.name)

    local num = self:GetCurPos()
    CfUtils.FillText(self.TxtNum, self:GetCurPos())
    --self.controller.gameObject.transform:SetSiblingIndex(3 - num)

    local isUnlock = QuestConfMgr:GetInstance():IsUnlockChapterById(data.id)
    KTool.SetActive(self.LockGroup, not isUnlock)
    KTool.SetActive(self.ImgPlay, isUnlock)

    local status = isUnlock and 1 or 2
    CfUtils.SetUISwitchImage(self.ImgChapterbg, status)
    CfUtils.SetUISwitchText(self.TxtChapter, status)
    CfUtils.SetUISwitchText(self.TxtNum, status)

    local isAllDraw = QuestConfMgr:GetInstance():IsAllDrawRewardId(self._data.id)
    CfUtils.SetActive(self.Finish, isAllDraw)

    --如果解锁了
    if isUnlock then
        if isAllDraw then
            self.ImgGiftIcon:MarkGray(true)
        else
            self.ImgGiftIcon:MarkGray(false)
        end
    else
        KTool.SetActive(self.BtnGetReward, false)
        self.ImgGiftIcon:MarkGray(true)
    end
    CfUtils.SetUISwitchImage(self.ImgCircle, status)

    CfUtils.SetActive(self.redPoint, QuestConfMgr:GetInstance():IsHasDrawRewardId(self._data.id)) 
end

function UIRolePlotChapterNode:GetCurPos()
    if not self._data then
        return 0
    end

    local allChapterId = QuestConfMgr:GetInstance():GetRoleStoryChapterIds(self._data.roleId)
    for k, v in pairs(allChapterId) do
        if checkNumber(self._data.id) == checkNumber(v) then
            return k
        end
    end
    return 0
end 

function UIRolePlotChapterNode:UpdatePosition(position)
    self.ChapterCell:Play(CS.UnityEngine.Animator.StringToHash("Go"), -1, position)
    self.ChapterCell.speed = 0
end

--播放剧情
function UIRolePlotChapterNode:PlayPlot(vo, endCb)
    if not vo then
        return
    end
    if self.isPlayPlot then
        return
    end
    self.isPlayPlot = true
    local plotIds = CfUtils.Split(vo.plotId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        return 
    end

    self.curPlotIndex = 1
    self:PlayPloting(plotIds, vo, endCb)
end

function UIRolePlotChapterNode:PlayPloting(plotIds, vo, endCb)
    local ChapterUtils = import('Game.Chapter.ChapterUtils')
    ChapterUtils.ProcessChapter(checkNumber(plotIds[self.curPlotIndex]), function(go)
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        self.RolePlot.gameObject.transform.localScale = Vector3(0, 0, 0)
        self._plotGo = go
    end, function()
        --所有的播完结束
        if self.curPlotIndex >= table.count(plotIds) then
            GameUtils.PlayMainBGM()
            if endCb then
                endCb()
            end

            self.RolePlot.gameObject.transform.localScale = Vector3(1, 1, 1)
            KTool.SafeDelete(self._plotGo)
            self.isPlayPlot = false
        else
            self.curPlotIndex = self.curPlotIndex + 1
            KTool.SafeDelete(self._plotGo)
            self:PlayPloting(plotIds, vo, endCb)
        end
    end)
end

function UIRolePlotChapterNode:OnBtnGift()
    CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UIPolePlotEndRewardPopupDialog, parameters = {id = self._data.id}}, {
        --{ id = Constants.UITypeIds.UIRolePlotDialog }
    })
end

function UIRolePlotChapterNode:OnBtnEnterChapter()
    local isUnlock, err = QuestConfMgr:GetInstance():IsUnlockChapterById(self._data.id)
    if not isUnlock then
        GameUtils.Toast(err)
        return
    end
    xRecord.record('4-006', "click_character_quest_"..self._data.roleId.."_"..self._data.id)

    CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UIPolePlotListDialog, parameters = {id = self._data.id}}, {
        { id = Constants.UITypeIds.UIRolePlotDialog }
    })
end

function UIRolePlotChapterNode:OnDestroy()
    Events.RemoveListener(Constants.EventNames.RedpointDataChange, self.eventRedpointDataChange)

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIRolePlotChapterNode
